use horizon_native_java::{NativeJar, StdHost, Value};
use std::{fs, process::Command};
const SOURCE: &str = r#"public class Probe { enum Plain { A,B } enum Body { A {}, B } static String rows(){ StringBuilder s=new StringBuilder(); for(Enum<?> e:new Enum<?>[]{Plain.A,Body.A,Body.B}){Class<?> c=e.getClass(),d=e.getDeclaringClass(); s.append(e).append("|").append(c.getName()).append("|").append(d.getName()).append("|").append(c==d).append("|").append(c.isEnum()).append("|").append(c.getEnclosingClass().getName()).append("\\n");} return s.toString(); }}"#;
#[test] fn balm_enum_rows_match_java25_oracle(){ let root=std::env::temp_dir().join("balm-enum-fixture"); let _=fs::create_dir_all(root.join("src")); fs::write(root.join("src/Probe.java"),SOURCE).unwrap(); let st=Command::new("javac").args(["--release","17","-d"]).arg(&root).arg(root.join("src/Probe.java")).status().unwrap(); assert!(st.success()); let jar=root.join("p.jar"); let st=Command::new("jar").args(["cf"]).arg(&jar).arg("-C").arg(&root).arg("Probe.class").status().unwrap(); assert!(st.success()); let j=NativeJar::from_path(&jar).unwrap(); let out=match j.invoke_method("Probe","rows","()Ljava/lang/String;",None,&mut StdHost::new()).unwrap(){Value::Ref(Some(s))=>s,_=>panic!()}; assert_eq!(out, include_str!("fixtures/balm_enum_oracle/java25.txt")); }
